command:
$ErrorActionPreference = 'Stop'
$forgeRoot = (Get-Location).Path
. '.forge-codex/instructions/scripts/Common.ps1'
& '.forge-codex/instructions/scripts/Verify-Ledger.ps1' -WorkspaceRoot $forgeRoot
& '.forge-codex/instructions/scripts/Validate-NoPython.ps1' -WorkspaceRoot $forgeRoot
& '.forge-codex/instructions/scripts/Validate-NoAttribution.ps1' -WorkspaceRoot $forgeRoot
& '.forge-codex/instructions/scripts/Validate-McpParity.ps1' -WorkspaceRoot $forgeRoot -ActualToolSnapshot (Join-Path $forgeRoot 'tests/fixtures/Mcp/mcp-tools-semantic-golden.json')
$forgeEvidenceRelative = '.forge-codex/state/evidence/P14/mcp-tool-contract-matrix-checkpoint.json'
$forgeEvidencePath = Join-Path $forgeRoot $forgeEvidenceRelative
$forgeEvidence = Read-JsonFile -Path $forgeEvidencePath
if ($forgeEvidence.status -ne 'passed' -or $forgeEvidence.gate_status -ne 'open' -or $forgeEvidence.effective_exit_code -ne 0) { throw 'P14 MCP semantic checkpoint status is invalid.' }
if ($forgeEvidence.measured_result.focused_ctest_passed -ne 3 -or $forgeEvidence.measured_result.contract_matrix_assertions -ne 1737 -or $forgeEvidence.measured_result.adapter_test_assertions -ne 470 -or $forgeEvidence.measured_result.native_filesystem_search_tests_passed -ne 5) { throw 'P14 MCP semantic measured result is invalid.' }
if ($forgeEvidence.measured_result.catalog_tools -ne 53 -or $forgeEvidence.measured_result.fixture_cases -ne 212 -or $forgeEvidence.measured_result.fixture_categories_per_tool -ne 4) { throw 'P14 MCP semantic matrix inventory is invalid.' }
$forgeBuildRecord = Read-JsonFile -Path (Join-Path $forgeRoot ([string]$forgeEvidence.build_test_command_record))
$forgeRecoveryRecord = Read-JsonFile -Path (Join-Path $forgeRoot ([string]$forgeEvidence.recovery_command_record))
if ($forgeBuildRecord.exit_code -ne 1 -or $forgeBuildRecord.timed_out -or $forgeRecoveryRecord.exit_code -ne 0 -or $forgeRecoveryRecord.timed_out) { throw 'P14 MCP command disposition is invalid.' }
foreach ($forgeRecord in @($forgeBuildRecord,$forgeRecoveryRecord)) {
  foreach ($forgeStreamName in @('stdout','stderr')) {
    $forgeStreamRelative = [string]$forgeRecord.$forgeStreamName
    $forgeStreamPath = Join-Path $forgeRoot $forgeStreamRelative
    if ((Get-FileSha256 -Path $forgeStreamPath) -ne [string]$forgeRecord."${forgeStreamName}_sha256") { throw "Command stream hash mismatch: $forgeStreamRelative" }
  }
}
$forgeBuildStdout = Get-Content -Raw -LiteralPath (Join-Path $forgeRoot ([string]$forgeBuildRecord.stdout))
$forgeBuildStderr = Get-Content -Raw -LiteralPath (Join-Path $forgeRoot ([string]$forgeBuildRecord.stderr))
if (-not $forgeBuildStdout.Contains('MCP tool-pack adapter tests passed: 470 assertions') -or -not $forgeBuildStdout.Contains('MCP tool contract matrix passed 1737 assertions across 53 tools and 212 cases.') -or -not $forgeBuildStdout.Contains('5/5 native filesystem/search tests passed.') -or -not $forgeBuildStdout.Contains('100% tests passed out of 3')) { throw 'Recorded CTest pass lines are incomplete.' }
if (-not $forgeBuildStderr.Contains("A parameter cannot be found that matches parameter name 'Depth'.")) { throw 'Recorded post-test failure signature is invalid.' }
foreach ($forgeArtifact in $forgeEvidence.artifacts) {
  $forgeArtifactPath = Join-Path $forgeRoot ([string]$forgeArtifact.path)
  $forgeArtifactItem = Get-Item -LiteralPath $forgeArtifactPath
  if ($forgeArtifactItem.Length -ne [int64]$forgeArtifact.bytes -or (Get-FileSha256 -Path $forgeArtifactPath) -ne [string]$forgeArtifact.sha256) { throw "Artifact mismatch: $($forgeArtifact.path)" }
}
foreach ($forgeSource in $forgeEvidence.source_evidence) {
  $forgeSourcePath = Join-Path $forgeRoot ([string]$forgeSource.path)
  if ((Get-FileSha256 -Path $forgeSourcePath) -ne [string]$forgeSource.sha256) { throw "Source mismatch: $($forgeSource.path)" }
}
$forgeFixture = Read-JsonFile -Path (Join-Path $forgeRoot 'tests/fixtures/Mcp/mcp-tool-contract-cases.json')
$forgeFixtureNames = @()
$forgeFixtureCases = 0
foreach ($forgeTool in $forgeFixture.tools) {
  $forgeFixtureNames += [string]$forgeTool.name
  $forgeCategories = @($forgeTool.cases.psobject.Properties.Name | Sort-Object)
  if (($forgeCategories -join ',') -ne 'boundary,dependency_error,invalid,valid') { throw "Fixture categories are invalid: $($forgeTool.name)" }
  $forgeFixtureCases += $forgeCategories.Count
}
if ($forgeFixture.tools.Count -ne 53 -or @($forgeFixtureNames | Sort-Object -Unique).Count -ne 53 -or $forgeFixtureCases -ne 212) { throw 'Fixture cardinality is invalid.' }
$forgeRunState = Read-JsonFile -Path (Join-Path $forgeRoot '.forge-codex/state/run-state.json')
$forgeP14 = $forgeRunState.phases | Where-Object id -eq 'P14'
$forgeG14 = $forgeRunState.gates | Where-Object id -eq 'G14'
if ($forgeRunState.active_phase -ne 'P14' -or $forgeRunState.active_role -ne 'builder' -or $forgeP14.status -ne 'in_progress' -or $forgeG14.status -ne 'in_progress') { throw 'Run-state phase or gate status is invalid.' }
foreach ($forgeExpectedEvidence in @([string]$forgeEvidence.build_test_command_record,[string]$forgeEvidence.qualified_postprocess_retry_record,[string]$forgeEvidence.recovery_command_record,$forgeEvidenceRelative,'.forge-codex/state/decisions/P14-008-source-compatible-mcp-semantics-and-windows-extensions.md')) {
  if ($forgeExpectedEvidence -notin $forgeP14.evidence -or $forgeExpectedEvidence -notin $forgeG14.evidence) { throw "Run-state is missing checkpoint evidence: $forgeExpectedEvidence" }
}
$forgeIndex = Read-JsonFile -Path (Join-Path $forgeRoot '.forge-codex/state/evidence-index.json')
$forgeIndexItem = $forgeIndex.items | Where-Object id -eq 'P14-mcp-tool-contract-matrix-checkpoint'
if (-not $forgeIndexItem -or [string]$forgeIndexItem.path -ne $forgeEvidenceRelative -or [string]$forgeIndexItem.sha256 -ne (Get-FileSha256 -Path $forgeEvidencePath)) { throw 'Evidence index checkpoint binding is invalid.' }
$forgeTextFiles = @(
  'CMakeLists.txt',
  'include/ForgeConductor/Mcp/McpToolPackAdapter.h',
  'src/Hosts/Cli/McpServeCompositionRoot.cpp',
  'src/Mcp/McpToolPackAdapter.cpp',
  'src/NativeTools/Windows/WindowsPathGlobService.cpp',
  'tests/Mcp/McpToolPackAdapterTests.cpp',
  'tests/NativeTools/WindowsFileSystemSearchTests.cpp',
  'tests/Mcp/McpToolContractMatrixTests.cpp',
  'tests/Mcp/McpToolContractTestSupport.cpp',
  'tests/Mcp/McpToolContractTestSupport.h',
  'tests/fixtures/Mcp/mcp-tool-contract-cases.json',
  '.forge-codex/state/decisions/P14-008-source-compatible-mcp-semantics-and-windows-extensions.md',
  $forgeEvidenceRelative,
  '.forge-codex/state/run-state.json',
  '.forge-codex/state/evidence-index.json'
)
foreach ($forgeTextRelative in $forgeTextFiles) {
  $forgeBytes = [IO.File]::ReadAllBytes((Join-Path $forgeRoot $forgeTextRelative))
  if ($forgeBytes.Length -ge 3 -and $forgeBytes[0] -eq 0xEF -and $forgeBytes[1] -eq 0xBB -and $forgeBytes[2] -eq 0xBF) { throw "UTF-8 BOM found: $forgeTextRelative" }
  $forgeText = [Text.Encoding]::UTF8.GetString($forgeBytes)
  if ([regex]::IsMatch($forgeText,'(?<!\r)\n') -or [regex]::IsMatch($forgeText,'\r(?!\n)') -or -not $forgeText.EndsWith("`r`n")) { throw "Non-CRLF formatting found: $forgeTextRelative" }
}
git diff --check
if ($LASTEXITCODE -ne 0) { throw 'git diff --check failed.' }
Write-Host 'P14 MCP semantic checkpoint integrity passed: 3/3 CTest tests, 470 adapter assertions, 1737 matrix assertions, 5/5 native tests, 53 tools and 212 cases.'
